add_action( 'woocommerce_after_single_product', 'perfectpixel_truncate_tag_list' );

function perfectpixel_truncate_tag_list() {
	$data = array(
		'visible' => max( 1, (int) '{{visible_tags_count}}' ),
		'more'    => '{{more_tags_text}}',
	);
	?>
	<script>
	( function ( cfg ) {
		document.querySelectorAll( '.product_meta .tagged_as' ).forEach( function ( box ) {
			var links = box.querySelectorAll( 'a[rel~="tag"]' );
			if ( links.length <= cfg.visible ) {
				return;
			}
			var hidden = [];
			links.forEach( function ( link, i ) {
				if ( i >= cfg.visible ) {
					// Wrap each extra link (with its leading comma) so it can be hidden.
					var wrap = document.createElement( 'span' );
					wrap.hidden = true;
					var prev = link.previousSibling;
					link.parentNode.insertBefore( wrap, link );
					if ( prev && 3 === prev.nodeType ) {
						wrap.appendChild( prev );
					}
					wrap.appendChild( link );
					hidden.push( wrap );
				}
			} );
			var more = document.createElement( 'a' );
			more.href = '#';
			more.textContent = ' ' + cfg.more.replace( '%d', hidden.length );
			more.addEventListener( 'click', function ( e ) {
				e.preventDefault();
				hidden.forEach( function ( el ) { el.hidden = false; } );
				more.remove();
			} );
			box.appendChild( more );
		} );
	} )( <?php echo wp_json_encode( $data ); ?> );
	</script>
	<?php
}
